// Patches the platform folders generated by `flutter create`.
// Adds Android network permissions and sets the display name "NetScan".
// Safe to run multiple times:  dart run tool/patch_platforms.dart
import 'dart:io';

void patch(String path, String Function(String) change) {
  final f = File(path);
  if (!f.existsSync()) return;
  final before = f.readAsStringSync();
  final after = change(before);
  if (after != before) {
    f.writeAsStringSync(after);
    stdout.writeln('patched $path');
  }
}

void main() {
  patch('android/app/src/main/AndroidManifest.xml', (s) {
    const perms = [
      'android.permission.INTERNET',
      'android.permission.ACCESS_NETWORK_STATE',
      'android.permission.ACCESS_WIFI_STATE',
      'android.permission.CHANGE_WIFI_MULTICAST_STATE',
    ];
    final block = perms
        .where((p) => !s.contains(p))
        .map((p) => '    <uses-permission android:name="$p"/>\n')
        .join();
    if (block.isNotEmpty) {
      final m = RegExp(r'<manifest[^>]*>\s*\n').firstMatch(s);
      if (m != null) s = s.replaceRange(m.end, m.end, block);
    }
    return s.replaceFirst(
        RegExp(r'android:label="[^"]*"'), 'android:label="NetScan"');
  });

  patch('windows/runner/main.cpp', (s) => s
      .replaceAll('L"netscan"', 'L"NetScan"')
      .replaceAll('Win32Window::Size size(1280, 720);',
          'Win32Window::Size size(1280, 820);'));

  patch('windows/runner/Runner.rc', (s) => s
      .replaceAll('"FileDescription", "netscan"', '"FileDescription", "NetScan"')
      .replaceAll('"ProductName", "netscan"', '"ProductName", "NetScan"')
      .replaceAll('"InternalName", "netscan"', '"InternalName", "NetScan"'));

  patch('windows/CMakeLists.txt',
      (s) => s.replaceAll('set(BINARY_NAME "netscan")', 'set(BINARY_NAME "NetScan")'));
}
